import {find,locate,isLocked,selectionRoots} from '../document/model.js';
import {escape} from '../renderer/svg.js';
export const studioMenuGroups=[
 ['File',[
  ['Project',[['New project','new-project'],['Open local project…','open-project'],['Save on this device','save-project'],['Duplicate project','duplicate-project'],['Composition settings…','settings'],['Open test composition','load-demo']]],
  ['Import',[['Project…','import-project'],['SVG artwork…','import-svg'],['Video reference…','studio-video-reference'],['Audio…','import-audio']]],
  ['Export',[['Project backup…','export-project'],['SVG artwork…','export-svg'],['Animation…','export']]],
  ['Help',[['How to animate','help']]]
 ]],
 ['Edit',[
  ['History',[['Undo','undo'],['Redo','redo']]],
  ['Clipboard',[['Copy objects','studio-copy'],['Cut objects','studio-cut'],['Paste objects','studio-paste']]],
  ['Selection',[['Multi-select','multi'],['Group','group'],['Ungroup','ungroup'],['Duplicate objects','duplicate'],['Delete objects','delete']]],
  ['Shape construction',[['Add rubber hose limb','studio-rubber-hose']]]
 ]],
 ['Options',[
  ['Workspace',[['Workspace settings…','workspace-settings'],['Light / dark mode','theme'],['Properties panel','studio-properties'],['Layers panel','studio-layers']]],
  ['Canvas',[['Canvas options…','canvas-options'],['Show / hide sequence','toggle-sequence']]],
  ['Animation',[['Add keyframe','add-key'],['Motion presets…','motion-presets'],['Keyframe options…','key-options'],['Sequencer options…','block-options'],['Playback range…','playback-range']]],
  ['Audio',[['Record audio','record'],['Stop recording','stop-record'],['Audio placement & trim…','audio-edit']]]
 ]]
];
// Flat command inventory remains available to callers; grouping has one source.
export const studioMenuDefinitions=studioMenuGroups.map(([name,groups])=>[name,groups.flatMap(([,items])=>items)]);
export function studioMenuMarkup(){return studioMenuGroups.map(([name,groups],menu)=>'<details class="studio-menu"><summary>'+name+'</summary><div class="studio-menu-commands">'+groups.map(([heading,items],group)=>'<section class="studio-menu-group" aria-labelledby="studio-menu-heading-'+menu+'-'+group+'" data-menu-group="'+heading+'"><h3 id="studio-menu-heading-'+menu+'-'+group+'">'+heading+'</h3>'+items.map(([label,id])=>'<button data-studio-command="'+id+'">'+label+'</button>').join('')+'</section>').join('')+'</div></details>').join('');}

export function studioLayerRows(p,collapsed=new Set()){const rows=[];function visit(list,depth){for(let i=list.length-1;i>=0;i--){const n=list[i];rows.push({n,depth});if(!collapsed.has(n.id))visit(n.children||[],depth+1);}}visit(p.layers,0);return rows;}
export function selectStudioLayer(a,id,extend=false){if(!find(a.doc,id))return;a.properties?.flush();a.stage?.finishPath();a.keyIds.clear();a.selected=extend?(a.selected.includes(id)?a.selected.filter(x=>x!==id):[...a.selected,id]):[id];a.nodeEdit=a.tool==='direct';a.render();}
export function studioLayerAction(a,action,id,value){const n=find(a.doc,id);if(!n)return false;if(action==='visible'||action==='lock'){if(action==='lock'&&isLocked(a.doc,id)&&!n.locked)return false;a.mutate(action==='visible'?'Layer visibility':'Layer lock',()=>n[action==='visible'?'visible':'locked']=!n[action==='visible'?'visible':'locked']);return true;}if(isLocked(a.doc,id))return false;if(action==='rename'){const name=String(value||'').trim().slice(0,120);if(!name)return false;a.mutate('Rename layer',()=>n.name=name);return true;}if(action==='raise'||action==='lower'){const entry=locate(a.doc,id),next=entry.index+(action==='raise'?1:-1);if(next<0||next>=entry.list.length)return false;a.mutate(action==='raise'?'Raise layer':'Lower layer',()=>{entry.list.splice(entry.index,1);entry.list.splice(next,0,n);});return true;}return false;}
function state(a){return a.studioMenus??={layersOpen:false,collapsed:new Set(),rename:null};}
const methodCommands={'studio-copy':'copyObjects','studio-cut':'cutObjects','studio-paste':'pasteObjects','studio-rubber-hose':'addRubberHose','studio-video-reference':'showVideoReference'};
export function studioCommand(a,id){if(methodCommands[id]){if(!disabled(a,id))return a[methodCommands[id]]();return;}if(id==='studio-layers'){const s=state(a);s.layersOpen=!s.layersOpen;renderStudioMenus(a);return;}if(id==='studio-properties'){document.querySelector('[data-properties]')?.click();return;}const source=document.getElementById(id);if(source&&!source.disabled)source.click();}
function disabled(a,id){if(methodCommands[id]){if(typeof a[methodCommands[id]]!=='function')return true;if(id==='studio-copy')return !selectionRoots(a.doc,a.selected).length;if(id==='studio-cut')return !selectionRoots(a.doc,a.selected).some(n=>!isLocked(a.doc,n.id));if(id==='studio-paste')return !a.objectClipboard?.length;return false;}if(id==='studio-properties'||id==='studio-layers')return false;const source=document.getElementById(id);return !source||source.disabled;}
export function renderStudioMenus(a){const s=state(a),nav=document.querySelector('#studio-menubar'),panel=document.querySelector('#studio-layers-panel');if(!nav||!panel)return;for(const command of nav.querySelectorAll('[data-studio-command]')){command.disabled=disabled(a,command.dataset.studioCommand);const source=document.getElementById(command.dataset.studioCommand);if(source?.hasAttribute('aria-pressed'))command.setAttribute('aria-pressed',source.getAttribute('aria-pressed'));}
 const toggle=nav.querySelector('[data-studio-layer-toggle]');toggle.setAttribute('aria-expanded',String(s.layersOpen));panel.hidden=!s.layersOpen;if(!s.layersOpen)return;if(panel.contains(document.activeElement)&&document.activeElement.matches('input'))return;
 const selected=a.selected.length===1?find(a.doc,a.selected[0]):null,locked=selected&&isLocked(a.doc,selected.id),entry=selected&&locate(a.doc,selected.id);panel.innerHTML=`<header><strong>Layers</strong><button data-studio-close aria-label="Close Layers">×</button></header><div class="studio-layer-selection"><button data-studio-command="multi" aria-pressed="${!!a.multi}">Multi-select ${a.multi?'on':'off'}</button><span role="status">${a.selected.length} selected</span></div><div class="studio-layer-list">${studioLayerRows(a.doc,s.collapsed).map(({n,depth})=>`<div class="studio-layer-row ${a.selected.includes(n.id)?'selected':''}" style="--layer-depth:${depth}"><button class="studio-layer-disclosure" data-studio-disclose="${n.id}" ${n.children?.length?'':'disabled'} aria-expanded="${!s.collapsed.has(n.id)}" aria-label="${s.collapsed.has(n.id)?'Expand':'Collapse'} ${escape(n.name)}">${n.children?.length?(s.collapsed.has(n.id)?'›':'⌄'):'·'}</button><button class="studio-layer-name" data-studio-select="${n.id}" aria-pressed="${a.selected.includes(n.id)}" title="${escape(n.name)}">${escape(n.name)}<small>${escape(n.type)}${isLocked(a.doc,n.id)?' · locked':''}</small></button><button data-studio-action="visible" data-object="${n.id}" aria-pressed="${n.visible}" aria-label="${n.visible?'Hide':'Show'} ${escape(n.name)}">${n.visible?'◉':'○'}</button><button data-studio-action="lock" data-object="${n.id}" aria-pressed="${n.locked}" aria-label="${n.locked?'Unlock':'Lock'} ${escape(n.name)}" ${isLocked(a.doc,n.id)&&!n.locked?'disabled title="Locked by parent group"':''}>${n.locked?'🔒':'🔓'}</button></div>`).join('')||'<p class="studio-empty">Draw a shape to create your first layer.</p>'}</div>${s.rename&&selected?.id===s.rename?`<form class="studio-layer-rename"><label>Layer name<input name="layer-name" value="${escape(selected.name)}" maxlength="120" required></label><button type="submit">Save name</button><button type="button" data-studio-cancel-rename>Cancel</button></form>`:''}<footer><button data-studio-rename ${!selected||locked?'disabled':''}>Rename</button><button data-studio-action="raise" data-object="${selected?.id||''}" ${!entry||locked||entry.index===entry.list.length-1?'disabled':''}>Raise</button><button data-studio-action="lower" data-object="${selected?.id||''}" ${!entry||locked||entry.index===0?'disabled':''}>Lower</button>${['group','ungroup','duplicate','delete'].map(id=>`<button data-studio-command="${id}" ${disabled(a,id)?'disabled':''}>${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}</footer>`;}
export function bindStudioMenus(a){if(document.querySelector('#studio-menubar'))return;const nav=document.createElement('nav');nav.id='studio-menubar';nav.className='studio-menubar';nav.setAttribute('aria-label','Application menus');if(document.documentElement)document.documentElement.dataset.studioMenus='true';nav.innerHTML=studioMenuMarkup()+'<button data-studio-layer-toggle aria-expanded="false" aria-controls="studio-layers-panel">Layers</button>';
 const slot=document.querySelector('#studio-menu-slot');if(slot)slot.append(nav);else document.querySelector('.topbar')?.insertBefore(nav,document.querySelector('#project-menu'));
 const panel=document.createElement('aside');panel.id='studio-layers-panel';panel.className='studio-layers-panel';panel.hidden=true;panel.setAttribute('aria-label','Layers');document.body.append(panel);const closeMenus=()=>nav.querySelectorAll('details[open]').forEach(d=>d.open=false);
 const command=e=>{const hit=e.target.closest('[data-studio-command]');if(hit&&!hit.disabled){closeMenus();const run=()=>studioCommand(a,hit.dataset.studioCommand);if(typeof requestAnimationFrame==='function')requestAnimationFrame(()=>setTimeout(run,0));else setTimeout(run,0);}};nav.addEventListener('click',e=>{if(e.target.closest('[data-studio-layer-toggle]'))studioCommand(a,'studio-layers');else command(e);});nav.querySelectorAll('details').forEach(d=>d.addEventListener('toggle',()=>{d.querySelector('summary').setAttribute('aria-expanded',String(d.open));if(d.open)nav.querySelectorAll('details').forEach(other=>{if(other!==d)other.open=false;});}));
 panel.addEventListener('click',e=>{const hit=e.target.closest('button');if(!hit||hit.disabled)return;if(hit.hasAttribute('data-studio-close')){state(a).layersOpen=false;state(a).rename=null;renderStudioMenus(a);nav.querySelector('[data-studio-layer-toggle]').focus();return;}if(hit.dataset.studioSelect)return selectStudioLayer(a,hit.dataset.studioSelect,a.multi||e.shiftKey);if(hit.dataset.studioDisclose){const s=state(a),id=hit.dataset.studioDisclose;s.collapsed.has(id)?s.collapsed.delete(id):s.collapsed.add(id);return renderStudioMenus(a);}if(hit.dataset.studioAction)return studioLayerAction(a,hit.dataset.studioAction,hit.dataset.object);if(hit.hasAttribute('data-studio-rename')){state(a).rename=a.selected[0];renderStudioMenus(a);const input=panel.querySelector('input');input?.focus();input?.select();return;}if(hit.hasAttribute('data-studio-cancel-rename')){state(a).rename=null;hit.blur();return renderStudioMenus(a);}command(e);});
 panel.addEventListener('submit',e=>{e.preventDefault();const id=state(a).rename;if(id&&studioLayerAction(a,'rename',id,new FormData(e.target).get('layer-name'))){state(a).rename=null;document.activeElement?.blur();renderStudioMenus(a);}});
 document.addEventListener('pointerdown',e=>{if(!nav.contains(e.target))closeMenus();});document.addEventListener('keydown',e=>{const open=nav.querySelector('details[open]');if(e.key==='Escape'&&(open||panel.contains(e.target))){e.preventDefault();e.stopImmediatePropagation();if(open){open.open=false;open.querySelector('summary').focus();}else{state(a).layersOpen=false;state(a).rename=null;renderStudioMenus(a);nav.querySelector('[data-studio-layer-toggle]').focus();}return;}if(!nav.contains(e.target))return;const menu=e.target.closest('details'),buttons=menu?[...menu.querySelectorAll('button:not(:disabled)')]:[],summaries=[...nav.querySelectorAll('summary')];if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(menu){menu.open=true;const index=buttons.indexOf(e.target),next=index<0?(e.key==='ArrowDown'?0:buttons.length-1):(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus();}}else if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();const current=menu?.querySelector('summary'),index=summaries.indexOf(current);closeMenus();summaries[(index+(e.key==='ArrowRight'?1:-1)+summaries.length)%summaries.length]?.focus();}},true);renderStudioMenus(a);}
